{
  "name": "Lumiloop LS 三轴电场探头",
  "name_en": "Lumiloop LS Three-Axis Electric Field Probe",
  "manufacturer": "Lumiloop",
  "description": "这是一种三轴电场场强探头，用于测量空间中电场的三个正交分量及合成场强。它适合实验室中的电磁场测试、场强校准和环境电场监测等用途。",
  "description_en": "This is a three-axis electric-field probe used to measure the three orthogonal components of an electric field and the resulting field magnitude. It is suitable for laboratory electromagnetic-field testing, field-strength calibration, and ambient electric-field monitoring.",
  "actions": [
    {
      "action_name": "auto-magnitude",
      "description": "读取合成电场强度。",
      "description_en": "Read the resultant electric-field magnitude."
    },
    {
      "action_name": "auto-magnitude_all",
      "description": "读取三轴电场分量及合成场强。",
      "description_en": "Read the three-axis electric-field components and the resultant field magnitude."
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置测量频率。",
      "description_en": "Get or set the measurement frequency."
    },
    {
      "action_name": "auto-mode",
      "description": "获取或设置测量模式。",
      "description_en": "Get or set the measurement mode."
    }
  ],
  "tag_hints": [
    "electric field probe",
    "three-axis field measurement",
    "field strength monitoring",
    "EMF testing",
    "electromagnetic calibration",
    "vector field magnitude"
  ]
}

